\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 I + 166 Bl.}}\plain \f1\lang1033\fs24   (gez\u228 \'e4hlt 165 Bl.; Doppelfoliierung 14a/14b [14a ist Schaltzettel mit Text, Ma\u223 \'dfe: 13 x 8,5 cm]), {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 27 x 21}}\plain \f1\lang1033\fs24   cm. (VII\endash 1)\plain \f1\super\lang1033\fs24 12\plain \f1\lang1033\fs24   + (IV+1)\plain \f1\super\lang1033\fs24 20\plain \f1\lang1033\fs24   + 2 IV\plain \f1\super\lang1033\fs24 36\plain \f1\lang1033\fs24   + (V\endash 2)\plain \f1\super\lang1033\fs24 44\plain \f1\lang1033\fs24   + 4 IV\plain \f1\super\lang1033\fs24 76\plain \f1\lang1033\fs24   + V\plain \f1\super\lang1033\fs24 86\plain \f1\lang1033\fs24   + IV\plain \f1\super\lang1033\fs24 94\plain \f1\lang1033\fs24   + (V\endash 2)\plain \f1\super\lang1033\fs24 102\plain \f1\lang1033\fs24   + IV\plain \f1\super\lang1033\fs24 110\plain \f1\lang1033\fs24   + (V\endash 2)\plain \f1\super\lang1033\fs24 118\plain \f1\lang1033\fs24   + 5 IV\plain \f1\super\lang1033\fs24 158\plain \f1\lang1033\fs24   + (IV\endash 1)\plain \f1\super\lang1033\fs24 165\plain \f1\lang1033\fs24 . Schriftspiegel: 20\endash 21,5 x 15\endash 15,5 cm. 1 Spalte. 23 Zeilen. {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Karolingische Minuskel}}\plain \f1\lang1033\fs24   von wechselnden H\u228 \'e4nden der Willihalm-Gruppe (siehe \plain \f1\scaps\lang1033\fs24 Daniel; Glauche\plain \f1\lang1033\fs24 ), an Anf\u228 \'e4ngen und auch im Flie\u223 \'dftext immer wieder Capitalis, rot geh\u246 \'f6ht (auch vergr\u246 \'f6\u223 \'dferte [2-3-zeilige] Initialen). Zahlreiche rot geh\u246 \'f6hte Majuskeln im Flie\u223 \'dftext. Vorderer und hinterer Spiegel fehlen.}

