\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Kreisschema (Windrose um Erdteile). 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Zeichnung. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Besitzeintrag (s. o.). 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paulus Orosius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Historia adversum paganos libri VII}}\plain \f1\lang1033\fs24 . 143\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Bibliotheksverzeichnis des Benediktinerklosters Saint-Evre de Toul. 146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 147\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Isidorus Hispalensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Chronica}}\plain \f1\lang1033\fs24 . 153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 154\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Chronik (anonym). 168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 169\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  vacat. Siehe \plain \f1\scaps\lang1033\fs24 Remak-Honnef\plain \f1\lang1033\fs24 .}

