\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   nachgetragene theologisch-katechetische Notizen. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Kalender (Kalendarium Walciodorense; siehe \plain \f1\scaps\lang1033\fs24 Borst\plain \f1\lang1033\fs24   2001). 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Erg\u228 \'e4nzungen zum Kalender. 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Mondstand bei verschiedenen Kirchenfesten. 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Mariengebet. 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 16\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Gebet des hl. Brendan. 18\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Vorwort des Hieronymus zum Psalterium. 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   weitere Prologe zum Psalterium. 26\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Psalterium}}\plain \f1\lang1033\fs24   (gro\u223 \'dfenteils mit Glossen). 174\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 231\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hymnarium}}\plain \f1\lang1033\fs24   (teils mit musikalischer Notation), Officium und Gebete. 232\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. }

