lain \f1\lang1033\fs24   Buch VIII; 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch IX; 140\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch X; 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 156\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch XI; 156\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch XII; 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 189\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch XIII; 189\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 205\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch XIV; 205\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch XV; 215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch XVI; 221\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 227\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch XVII; 227\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 238\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch XVIII; 238\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 254\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch XIX). 254\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 266\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Josephus Flavius, Zusammenfassung. 266\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 269\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant. }

