\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Einzelblatt (= abgel\u246 \'f6ster alter Spiegel), beidseitig beschriebenes Fragment mit 2-spaltigem Text (Naturkunde?). 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Petrus Comestor}}\plain \f1\lang1033\fs24   (= Petrus Manducator), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sermones}}\plain \f1\lang1033\fs24 . 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Richardus de Sancto Victore}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De tribus approbriatis personis in Trinitate}}\plain \f1\lang1033\fs24   (an Magister Bernardum). 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 76\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bernardus Silvestris}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cosmographia}}\plain \f1\lang1033\fs24 . 76\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Evangelist Johannes, Sequentia. 76\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 77\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Sermones. 77\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Nachtr\u228 \'e4ge (wenig sp\u228 \'e4ter). 78\plain \f1\super\lang10