\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24   (z. B. Vorsatz verso): 2\endash 3-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1 cm) mit Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: Voluten, konturbegleitende F\u228 \'e4den \endash  teils mit gekurvten Partien oder mit Halbpalmetten. Binnenraum: Voluten, vertikale gerade F\u228 \'e4den, gebogte F\u228 \'e4den (an den Enden spiralig eingerollt), Perlen. }

