\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Marmorpapier. I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Mannheimer Eintr\u228 \'e4ge. II\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash III\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 160\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augustinus}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 158\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De trinitate libri XV}}\plain \f1\lang1033\fs24  ; zu 158\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   siehe auch \plain \f1\scaps\lang1033\fs24 Jullien\plain \f1\lang1033\fs24   / \plain \f1\scaps\lang1033\fs24 Perelman\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  [zu angef\u252 \'fcgtem Text von\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  Alkuin]; 158\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tractatus de creatione primi hominis}}\plain \f1\lang1033\fs24  ; 159\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 160\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Epistula CCX. 160\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Flores; siehe\plain \f1\scaps\lang1033\fs24  Remak-Honnef\plain \f1\lang1033\fs24   / \plain \f1\scaps\lang1033\fs24 Hauke\plain \f1\lang1033\fs24 ). 161\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 163\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant. 163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buntpapier.}

