\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Teile des Ehevertrags zwischen Johann Savran\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  (Sekret\u228 \'e4r von {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Charles de Gontaut}}\plain \f1\lang1033\fs24 , Duc de Biron [1562-1602]) und Anthonia Vallot, um 1600. 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Eusebius Caesariensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Historia ecclesiastica}}\plain \f1\lang1033\fs24   (3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Prologus und Kapitel\u252 \'fcbersicht; 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch I; 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch II; 22\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch III; 32\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch IV; 41\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch V; 51\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch VI; 61\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch VII; 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch VIII; 74\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch IX; 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch X; 87\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 93\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch XI [= Erg\u228 \'e4nzung von Rufinus Aquileiensis]). 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 109\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Iordanes Gotus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De actibus romanorum}}\plain \f1\lang1033\fs24 . 110\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 129\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Iordanes Gotus, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De origine Getarum}}\plain \f1\lang1033\fs24 . 130\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 131\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   weitere Teile des nachtr\u228 \'e4glich eingef\u252 \'fcgten Ehevertrags (siehe 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). }

