\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Pergamentfragment. II\plain \f1\super\lang1033\fs24 r\endash v \plain \f1\lang1033\fs24   querst\u228 \'e4ndiger Ausschnitt aus Prologus zu den Satirae des Persius (11. Jh. [siehe \plain \f1\scaps\lang1033\fs24 K\plain \f1\scaps\lang1033\fs24 \u246 \'f6\plain \f1\scaps\lang1033\fs24 bler\plain \f1\lang1033\fs24  ; \plain \f1\scaps\lang1033\fs24 Siewert\plain \f1\lang1033\fs24  ]). 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Aulus Persius Flaccus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Prologus zu den Satirae}}\plain \f1\lang1033\fs24   (mit volkst\u252 \'fcmlichen Glossen; vielleicht waren daf\u252 \'fcr die Glossen des {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Clm 19478}}\plain \f1\lang1033\fs24   vorbildhaft; siehe \plain \f1\scaps\lang1033\fs24 Siewert\plain \f1\lang1033\fs24 , S. 80). 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Aulus Persius Flaccus, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Satirae mit Glossen}}\plain \f1\lang1033\fs24 . 26\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 33\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Quintus Horatius Flaccus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De arte poetica}