\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 2\endash 6-zeilige rote und blaue Lombarden (Init.-H\u246 \'f6he: 0,5\endash 1,5 cm) im Wechsel, mit Fleuronn\u233 \'e9e in der Gegenfarbe (daneben auch sehr schlichter Besatz mit Palmettenfleuronn\u233 \'e9e an r\u246 \'f6mischen Zahlen am Seitenrand). Besatz (\u252 \'fcberwiegend links angesetzt): vertikale oder schr\u228 \'e4g abstehende Stege mit Palmettenfleuronn\u233 \'e9e, verstreute Einzelperlen, Voluten, Einzelf\u228 \'e4den mit Haarnadelkurve. Binnenraum: Palmetten, konturbegleitender Steg, Perlen, Fadenvoluten. Zus\u228 \'e4tzlich h\u228 \'e4ufig an schlichte Initialen angeh\u228 \'e4ngte schr\u228 \'e4g abstehende oder vertikale St\u228 \'e4be, manchmal auch leichte Kurven in zweifarbigem Fleuronn\u233 \'e9e (z. B. 109\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 118\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 131\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 216\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): axialsymmetrisch um den zentralen Faden \endash  der partiell durch Perlenkette ersetzt sein kann \endash  sitzen Palmetten, gestielte Drei- und Vierbl\u228 \'e4tter, Knospen (auch au\u223 \'dfen gefranst), Einzelf\u228 \'e4den mit Haarnadelkurven.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

