\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 2\endash 6-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1\endash 3 cm), mit Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: Schaftverl\u228 \'e4ngerungen und links vertikal flankierende Einzelf\u228 \'e4den mit Palmettenfleuronn\u233 \'e9e bzw. mit Halbpalmetten, Einzelperlen, Voluten, Ausl\u228 \'e4ufern mit Endeinrollung. Binnenraum: H\u246 \'f6rnchen, Voluten, Halbpalmetten, Perlen. }

