\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Kleine {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 2\endash 10-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 0,5\endash 2,5 cm), mit Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: um Initiale sitzende konturbegleitende oder vertikale F\u228 \'e4den und Stege mit eingerollten Enden und anhaftenden Perlen, zus\u228 \'e4tzlich links nach oben und unten erweitert \u252 \'fcber gr\u246 \'f6\u223 \'dfere Voluten in geschwungene Parallelstege mit anhaftenden \endash  oft zu gr\u246 \'f6\u223 \'dferen Konstellationen vereinten \endash  Halbpalmetten, Perlen (einzeln, Pyramiden), S-Kringeln, Staubf\u228 \'e4den und Voluten, umstreut von Perlen (einzeln, Ketten), schlie\u223 \'dflich in Einzelf\u228 \'e4den (oft mit Kurve oder Haarnadelkurve) auslaufend; gelegentlich auch verl\u228 \'e4ngerter Initialschaft mit Fischgr\u228 \'e4tenmuster besetzt. Binnenraum: konturbegleitende oder vertikale Stege, H\u246 \'f6rnchen, Voluten, Staubf\u228 \'e4den, gelappte Profilbl\u228 \'e4tter, Halbpalmetten, Einzelperlen.}

