\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \-\endash 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Isaac Iudaeus}}\plain \f1\lang1033\fs24   (= Isaac Ben Salomon), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber dietarum}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   zeitgen\u246 \'f6ssisches Kapitelverzeichnis; 82\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   sp\u228 \'e4terer Nachtrag). 82\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber elementorum}}\plain \f1\lang1033\fs24   (unvollst\u228 \'e4ndig; siehe \plain \f1\scaps\lang1033\fs24 Rothschild\plain \f1\lang1033\fs24 ). 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber febrium}}\plain \f1\lang1033\fs24   (5 B\u252 \'fccher; von Constantinus Africanus aus dem Arabischen \u252 \'fcbersetzt; 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   sehr viel sp\u228 \'e4ter nachgetragene Inhaltsangabe der Hs.). 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 142\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 167\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Idem, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber urinarum}}\plain \f1\lang1033\fs24 . 168\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   medizinischer Nachtrag (14./15. Jh.). 168\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat.}

