\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Exzerpte u. a. aus Schriften zur Physiognomie. 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 3\plain \f1\super\lang1033\fs24 r\plain \f2\lang1033\fs22\cf18  \plain \f1\lang1033\fs24\cf1 Liber introductorius parvus Rasis.\plain \f1\lang1033\fs24   3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 166\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Abubecrus Rasis}}\plain \f1\lang1033\fs24   (= \plain \f3\fs24 R\u257 \'e2z\u299 \'ee, Mu\plain \f1\lang1033\fs24  \u7717 ?\plain \f3\fs24 ammad Ibn-Zakar\u299 \'eey\u257 \'e2), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f3\fs24\chcbpat17 Liber almansoris}}\plain \f3\fs24  \plain \f1\lang1033\fs24  (von Gerardus Cremonensis aus dem Arabischen \u252 \'fcbersetzt; 10 B\u252 \'fccher). 167\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 226\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Abubecrus Rasis, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber divisionum}}\plain \f1\lang1033\fs24 . 226\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Zahlentabellen. 227\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 245\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Abubecrus Rasis, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Antidotarium}}\plain \f1\lang1033\fs24 . 245\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 246\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Zahlentabellen. 246\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 247\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 285\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Abubecrus Rasis, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Experimenta}}\plain \f1\lang1033\fs24   (und weitere Texte). 285\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 291\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Synonima Rasi (alphabetisch). 291\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 292\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Rezepte und medizinische Notizen. 292\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   mit Papier verklebt (wohl abgel\u246 \'f6ster hinterer Spiegel). }

