\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash III\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   nachtr\u228 \'e4gliche Widmung (f\u252 \'fcr Georg IV. Ludwig von Leuchtenstein, dem der Arzt Johann Georg Agricola aus Amberg [1558\endash 1633] diese Bibel geschenkt hatte, 1613 datiert). 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 483\plain \f1\super\lang1033\fs24 v{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\super\lang1033\fs24\chcbpat17  }}{\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Biblia sacra}}\plain \f1\lang1033\fs24 , Altes Testament. 484\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 589\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Biblia sacra, Neues Testament. 590\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 605\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Interpretationes nominum hebraicorum}}\plain \f1\lang1033\fs24 . 605\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 612\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  vacant. }

