\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 2\endash 19-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1\endash 7 cm) mit Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: oft nur im Quadrat von vier Einzelperlen, Fadenspiralen und Halbpalmetten (vereinzelt mit sog. \u8222 \'84pointing-finger-Motiv\ldblquote ) umstreut sowie links mit kurzen Einzelfadenausl\u228 \'e4ufern \endash  h\u228 \'e4ufig an Staubf\u228 \'e4den angesetzt \endash  in Haarnadelkurve endend; h\u228 \'e4ufig jedoch starker Vertikalzug, der nach unten langgezogenen geraden (manchmal auch schr\u228 \'e4g abstehenden) Ausl\u228 \'e4ufer aufweist, an dem einseitig in regelm\u228 \'e4\u223 \'dfigen Abst\u228 \'e4nden Konstellationen aus zwei Halbpalmetten und Einzelf\u228 \'e4den in Haarnadelkurve haften oder der als Fleuronn\u233 \'e9estab mit beidseitig zweifarbig angesetztem Repetitionsmuster (Perlenpyramiden [meist aus 3 oder 5 Perlen] an langem Stiel oder noch gr\u246 \'f6\u223 \'dfere Perlenkonstellationen [mehrfach aufeinander folgender Wechsel zwischen 1 und 2 Perlen], Fischgr\u228 \'e4tenmuster, schr\u228 \'e4g abstehende Halbpalmetten mit Kern, Folge von gegenst\u228 \'e4ndigen Voluten, kurze Querf\u228 \'e4den, seitlich schr\u228 \'e4g abstehende Einzelf\u228 \'e4den etc.) gestaltet ist. Binnenraum: Halbpalmetten, H\u246 \'f6rnchen, Fadenspiralen, Perlen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

