\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   ausgeschnittene Beschreibung der Hs. aus dem Katalog von Franz Trau eingeklebt.  I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat.\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  Biblia sacra. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hieronymus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Prolog zum Pentateuch}}\plain \f1\lang1033\fs24 . 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 325\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Altes Testament}}\plain \f1\lang1033\fs24 . 325\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 406\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Neues Testament}}\plain \f1\lang1033\fs24 . 407\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 424\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber hymnorum}}\plain \f1\lang1033\fs24 . Siehe \plain \f1\scaps\lang1033\fs24 Kudorfer.}

