\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Kleine {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24 : 2\endash 6-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 0,5\endash 2,5 cm) mit Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: vertikale F\u228 \'e4den oder Stege mit anhaftenden Perlen (einzeln, Kette) sowie S-Kringeln, nach oben und unten in Haarnadelkurve oder einzeln mit Einrollung endend. Binnenraum: vertikaler Faden oder Steg, teils mit perlenartiger Ausbuchtung oder anhaftender Perle. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

