\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt: \plain \f1\lang1033\fs24  2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 53\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Iustinianus imperator}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Institutiones}}\plain \f1\lang1033\fs24 . 53\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 54\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Kapitel\u252 \'fcbersicht zu Institutiones. 54\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Kapitel\u252 \'fcbersicht zu Tancredus. 55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tancredus Bononiensis}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ordo iudiciarius}}\plain \f1\lang1033\fs24   (55\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 71\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   pars 1; 71\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   pars 2; 103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat; 104\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   pars 3). 152\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 153\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Notabilia decretalium}}\plain \f1\lang1033\fs24 . 154\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Roffredus de Epiphanio}}\plain \f1\lang1033\fs24 ,{\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  De iure canonico}}\plain \f1\lang1033\fs24   (183\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat). 206\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 207\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 210\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Regulae iuris (Exzerpt). 210\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 214\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lectio de arbore consanguinitatis et affinitatis}}\plain \f1\lang1033\fs24   (212\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  / 213\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacant). 214\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Definitionen juristischer Begriffe und Merkvers. 215\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 221\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Tituli der Dekretalen. Siehe auch \plain \f1\scaps\lang1033\fs24 Hauke.}

