\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes de Sacrobosco}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Algorismus vulgaris}}\plain \f1\lang1033\fs24 . 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 63\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Idem,\plain \f1\super\lang1033\fs24  {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De sphaera}}\plain \f1\lang1033\fs24 . 63\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 66\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Komputistische Tabellen. 66\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  Petrus de Dacia, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tabula}}\plain \f1\lang1033\fs24 . 67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 72\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kalender}}\plain \f1\lang1033\fs24   (67\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   nachgetragene Notiz zur Zeitrechnung mit Verweis auf das Jahr 1414). 73\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Johannes de Sacrobosco, {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De computo ecclesiastico}}\plain \f1\lang1033\fs24 . 141\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cisio janus}}\plain \f1\lang1033\fs24 . 142\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Komputistische Tabellen. 143\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 148\plain \f1\super\lang1033\fs24 r {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kalender}}\plain \f1\lang1033\fs24 . 149\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Komputistische Tabellen. 152\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24    nachgetragene Ostertafeln. 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Kommentar zu Johannes de Sacrobosco, De computo ecclesiastico. 163\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 164\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Kardinal- und Ordinalzahlen. 164\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ars divinandi}}\plain \f1\lang1033\fs24 . 166\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 168\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Nachtr\u228 \'e4ge (Tabellen, komputistische Notizen). Siehe \plain \f1\scaps\lang1033\fs24 Remak-Honnef\plain \f1\lang1033\fs24 .}

