3\fs24 ) (Phil). 456\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[67]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paulus}}\plain \f1\lang1033\fs24   und weitere Figur, in P(\plain \f1\i\lang1033\fs24  aulus apostolus\plain \f1\lang1033\fs24 ) (Col). 457\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[68]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paulus}}\plain \f1\lang1033\fs24   und badende Figur (?), in P(\plain \f1\i\lang1033\fs24  aulus et Silvanus\plain \f1\lang1033\fs24 ) (I Th). 458\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[69]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gottvater, Paulus}}\plain \f1\lang1033\fs24   und weitere Figur, in P(\plain \f1\i\lang1033\fs24  aulus et Silvanus\plain \f1\lang1033\fs24 ) (II Th). 459\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   zwei Personen vor dem {\field{\*\fldinst HYPERLINK "hida://5500[73]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bischof}}\plain \f1\lang1033\fs24 , in P(\plain \f1\i\lang1033\fs24  aulus apostolus Iesu Christi\plain \f1\lang1033\fs24 ) (I Tim). 460\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   predigender {\field{\*\fldinst HYPERLINK "hida://5500[70]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paulus}}\plain \f1\lang1033\fs24   und Soldat, in P(\plain \f1\i\lang1033\fs24  aulus apostolus Iesu Christi\plain \f1\lang1033\fs24 ) (II Tim). 461\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Sch\u252 \'fcler wird gez\u252 \'fcchtigt, in P(\plain \f1\i\lang1033\fs24  aulus servus dei\plain \f1\lang1033\fs24 ) (Tit). 461\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[72]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bischof}}\plain \f1\lang1033\fs24   und zwei weitere Personen, in P(\plain \f1\i\lang1033\fs24  aulus apostolus\plain \f1\lang1033\fs24 ) (Phlm). 462\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   predigender {\field{\*\fldinst HYPERLINK "hida://5500[71]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Paulus}}\plain \f1\lang1033\fs24   vor zwei Zuh\u246 \'f6rern, in M(\plain \f1\i\lang1033\fs24  ultipharie\plain \f1\lang1033\fs24 ) (Hbr). 466\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   versammelte {\field{\*\fldinst HYPERLINK "hida://5500[74]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Apostel}}\plain \f1\lang1033\fs24   und himmelfahrender Jesus, in P(\plain \f1\i\lang1033\fs24  rimum quidem\plain \f1\lang1033\fs24 ) (Act). 479\plain \f1\super\lang1033\fs24 v \plain \f1\lang1033\fs24  stehender {\field{\*\fldinst HYPERLINK "hida://5500[75]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jacobus}}\plain \f1\lang1033\fs24 , als I(\plain \f1\i\lang1033\fs24  acobus\plain \f1\lang1033\fs24 ) (Iac). 480\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   stehender {\field{\*\fldinst HYPERLINK "hida://5500[76]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Petrus}}\plain \f1\lang1033\fs24   mit Schl\u252 \'fcssel, in P(\plain \f1\i\lang1033\fs24  etrus apostolus\plain \f1\lang1033\fs24 ) (I Pt). 482\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   stehender {\field{\*\fldinst HYPERLINK "hida://5500[77]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Petrus}}\plain \f1\lang1033\fs24   mit Schl\u252 \'fcssel, in S(\plain \f1\i\lang1033\fs24  imon Petrus servus et apostolus\plain \f1\lang1033\fs24 ) (II Pt). 483\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   stehender {\field{\*\fldinst HYPERLINK "hida://5500[78]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes}}\plain \f1\lang1033\fs24 , in Q(\plain \f1\i\lang1033\fs24  uod fuit ab initio\plain \f1\lang1033\fs24 ) (I Io). 484\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   stehender Johannes, in S(\plain \f1\i\lang1033\fs24  enior electe domine\plain \f1\lang1033\fs24 ) (II Io). 484\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   stehender {\field{\*\fldinst HYPERLINK "hida://5500[79]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes}}\plain \f1\lang1033\fs24 , in S(\plain \f1\i\lang1033\fs24  enior Gaio karissimo\plain \f1\lang1033\fs24 ) (III Io); stehender Heiliger mit Buch, als I(\plain \f1\i\lang1033\fs24  udas Iesu Christi servus\plain \f1\lang1033\fs24 ) (Iud). 485\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   am Schreibpult unter Architektur sitzender {\field{\*\fldinst HYPERLINK "hida://5500[80]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes}}\plain \f1\lang1033\fs24 , in A(\plain \f1\i\lang1033\fs24  pocalipsis Iesu Christi\plain \f1\lang1033\fs24 ) (Apc).}

