\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat (= abgel\u246 \'f6ster vorderer Spiegel). I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Eintrag und zwei Exlibris (s. o.). II\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   ganz oben Reste eines ansonsten abgeschnittenen Textes (?). II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   verschiedene Eintr\u228 \'e4ge zu medizinischen Fragen, 14./15. Jh. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannicius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Isagoge in medicinam}}\plain \f1\lang1033\fs24   (ad Tegni Galieni). 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 72\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Hippocrates}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Aphorismi mit Kommentar des Galenus}}\plain \f1\lang1033\fs24 . 72\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 73\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 170\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[2].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Galenus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Lectura super Tegni mit Kommentar des Ali ibn Ridwan (Haly Rodohan)}}\plain \f1\lang1033\fs24 . 170\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 171\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 220\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Hippocrates, {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber Prognosticorum mit Kommentar des Galenus}}\plain \f1\lang1033\fs24 . 220\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 304\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Hippocrates, {\field{\*\fldinst HYPERLINK "hida://bezwrk[4].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De regimine auctorum mit Kommentar des Galenus}}\plain \f1\lang1033\fs24   (Bl. 304\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   datiert: \plain \f1\i\lang1033\fs24  scripti Parisius anno gracie 1282\plain \f1\lang1033\fs24 ). 304\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 305\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 308\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[3].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Philaretus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[5].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De pulsibus}}\plain \f1\lang1033\fs24 . 308\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 316\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[4].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Theophilus}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[6].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 De urina}}\plain \f1\lang1033\fs24 . 316\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 317\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[5].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes de Sancto Amando}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[7].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Concordanciae}}\plain \f1\lang1033\fs24   (Nachtrag, unvollst\u228 \'e4ndig). 317\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   sp\u228 \'e4tere Eintr\u228 \'e4ge (kurze medizinische Notizen). 318\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Inhaltsangabe der Handschrift, 14. Jh. (= abgel\u246 \'f6ster hinterer Spiegel).  }

