\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat. I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   sp\u228 \'e4tere Notiz, Besitzeintrag (s. o.). II\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   nachgetragenes Inhaltsverzeichnis. II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   gro\u223 \'dfenteils getilgter Text mit Kommentar, sp\u228 \'e4tere Notizen. III\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash IV\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes Andreae}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kommentar zum 4. Buch der Decretales}}\plain \f1\lang1033\fs24 . 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 210\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gregorius IX., Papa}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber extra}}\plain \f1\lang1033\fs24   (= Decretalium libri V) mit Glossen u. a. von Raimundus de Pennaforti (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 50\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  Buch I; 50\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch II; 93\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 139\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch III; 141\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Buch IV; 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 210\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Buch V; 140\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Einschub: Brief von Papst Clemens IV. [an Dominikaner- und Franziskanerm\u246 \'f6nche]). 211\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Besitzvermerk (s. o.). 211\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Tabelle mit arabischen Zahlen in 5 Spalten (als einstiger hinterer Spiegel alte Klebespuren). }

