\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24   (z. B. 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 86\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 230\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 296\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 309\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): 2\endash 10-zeilige blaue Lombarden (Init.-H\u246 \'f6he: 1\endash 4 cm) mit rotem Fleuronn\u233 \'e9e. Besatz: seitliche (meist nur links) vertikale F\u228 \'e4den und Stege mit anhaftenden Einzelperlen (selten auch Perlenketten) oder perlenartigen Ausbuchtungen und eingerolltem Ende \endash  vereinzelt auch mit Haarnadelkurve, schlaufenartigen gro\u223 \'dfen \u220 \'dcberkreuzungen, Halbpalmetten sowie mit vertikal angeh\u228 \'e4ngten Fleuronn\u233 \'e9est\u228 \'e4ben (z. B. 296\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 309\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): rote und blaue Kreissegmente oder Keile mit S\u228 \'e4gez\u228 \'e4hnen. Binnenraum: vertikale F\u228 \'e4den oder Stege (vereinzelt mit anhaftenden Perlen), verzweigte und eingerollte Stege mit Perlen, Knospen (meist H\u228 \'e4ufen), Profilbl\u228 \'e4ttern. Auf Bl. 68\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 125\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   zus\u228 \'e4tzlich blaue Majuskeln der 1. Zeile (\plain \f1\i\lang1033\fs24  Gregorius\plain \f1\lang1033\fs24 ) vergr\u246 \'f6\u223 \'dfert und mit etwas schlichtem Fleuronn\u233 \'e9e umgeben.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

