\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat (nur Besitzvermerk s. o.). I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. S. 1\endash 47 {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Aristoteles}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liber de elenchis}}\plain \f1\lang1033\fs24 . S. 48 vacat (oben kleine Notiz). S. 49\endash 144 Aristoteles, {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Topica}}\plain \f1\lang1033\fs24 . S. 145\endash 219 Aristoteles, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Priora analytica}}\plain \f1\lang1033\fs24 . S. 220 Tabelle mit r\u246 \'f6mischen Zahlen. S. 221\endash 326 {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Porphyrius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[3].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Isagoge}}\plain \f1\lang1033\fs24 . S. 327 Nachtrag zu Aristoteles.}

