\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Kleine {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24   (z. B. S. 2, 3, 4, 7, 10): 2\endash 5-zeilige rote und blaue Lombarden (Init.-H\u246 \'f6he: 1\endash 2 cm), mit Fleuronn\u233 \'e9e in der Gegenfarbe. Besatz: Palmettenfleuronn\u233 \'e9e. Binnenraum: H\u246 \'f6rnchen, Ranken, Palmetten oder Halbpalmetten.}

