\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. II\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   theologische Notizen.\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 132\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24\cf1  {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bernardus Bottonius}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Casus super V libris Decretalium}}\plain \f1\lang1033\fs24   (1. Buch: 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ; 2. Buch: 28\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 58\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; 3. Buch: 58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ; 4. Buch: 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 102\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ; 5. Buch: 103\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 132\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ). 133\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   theologische Notizen (\u228 \'e4hnlich Bl. II). 134\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Raimundus de Pennaforti}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://bezwrk[1].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Summa de matrimonio}}\plain \f1\lang1033\fs24 . 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash \plain \f1\lang1033\fs24\cf1 148\plain \f1\super\lang1033\fs24\cf1 r\plain \f1\lang1033\fs24\cf1  \plain \f1\lang1033\fs24  Bernardus Bottonius, {\field{\*\fldinst HYPERLINK "hida://bezwrk[2].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Casus constitutionum novarum Innocentii IV}}\plain \f1\lang1033\fs24 . 148\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Inhalts\u252 \'fcbersicht zu den Constitutiones. 151\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 152\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Juristische Notizen, teils querst\u228 \'e4ndig. 153\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 160\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Bernardus Bottonius, Casus constitutionum novarum Innocentii IV. 161\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   Nachtr\u228 \'e4ge des fr\u252 \'fchen 14. Jhs., teils getilgt.}

