\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   vacat (Titelnennung). I\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash II\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 111\plain \f1\super\lang1033\fs24 r\plain \f1\b\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Petrus de Tarantasia}}\plain \f1\lang1033\fs24   (= Innocentius V., Papa), {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Commentarius in librum secundum Sententiarum}}\plain \f1\lang1033\fs24 . 111\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 112\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Verzeichnis der Distinktionen und Qu\u228 \'e4stionen. 112\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 113\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant. Siehe \plain \f1\scaps\lang1033\fs24 Wunderle\plain \f1\lang1033\fs24 . }

