\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 {\field{\*\fldinst HYPERLINK "hida://5260[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Pergament}}\plain \f1\lang1033\fs24   (2 ungez\u228 \'e4hlte Vorsatzbl. und 2 ungez\u228 \'e4hlte Nachsatzbl. Papier [zwischen beiden Nachsatzbl\u228 \'e4ttern weitere 5 Bl\u228 \'e4tter eingef\u252 \'fcgt, auf denen einseitig mit Schreibmaschine einiges zu Geschichte und Inhalt der Hs. notiert ist]), {\field{\*\fldinst HYPERLINK "hida://5706[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 141 Bl.}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5360[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 25,5 x 19,5}}\plain \f1\lang1033\fs24   cm. 17 IV\plain \f1\super\lang1033\fs24 136\plain \f1\lang1033\fs24   + (II+1)\plain \f1\super\lang1033\fs24 141\plain \f1\lang1033\fs24 . Schriftspiegel: 20,5\endash 22,5 x 15\endash 16 cm. 2 Spalten. 32\endash 38 Zeilen. {\field{\*\fldinst HYPERLINK "hida://5704[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Gotische Minuskeln}}\plain \f1\lang1033\fs24   von wechselnden H\u228 \'e4nden. Rubriziert. Teils rot geh\u246 \'f6hte Majuskeln im Flie\u223 \'dftext. Vereinzelt rote Unterstreichungen. Jeweils vorderer und hinterer Spiegel und ansto\u223 \'dfendes Vor- bzw. Nachsatzbl. Buntpapier [Kamm- und Schneckenmarmorpapier in Hellblau-, Braun- und Ockert\u246 \'f6nen, Schwarz], 20. Jh.; auf den Au\u223 \'dfenkanten der Spiegel jeweils zus\u228 \'e4tzlich goldene Ornamentleiste). {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Goldschnitt}}\plain \f1\lang1033\fs24 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Calibri;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

