\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Miniaturen}}\plain \f1\lang1033\fs24   (Farben wie ornamentale Initialen der 1. Hand, zus\u228 \'e4tzlich Gr\u252 \'fcn, Pinselgold; Szenen einspaltig [5,5\endash 7,5 x 5\endash 6 cm). 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Tod Adams}}\plain \f1\lang1033\fs24   (Hinweis auf den ersten S\u252 \'fcndenfall der biblischen Geschichte); {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Moses empf\u228 \'e4ngt die Gesetze}}\plain \f1\lang1033\fs24 . 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Verk\u252 \'fcndigung an Maria}}\plain \f1\lang1033\fs24 . 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Ankunft des Herrn. 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   hl. Nikolaus spendet Gold. 22\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   ein Ochsengespann versucht vergeblich, die {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Lucia}}\plain \f1\lang1033\fs24   in Bewegung zu setzen. 23\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Apostel Thomas}}\plain \f1\lang1033\fs24 . 27\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Christi Geburt}}\plain \f1\lang1033\fs24 . 31\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Verbrennung der hl. Anastasia. 33\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Steinigung des {\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Stephanus}}\plain \f1\lang1033\fs24 . 36\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Johannes}}\plain \f1\lang1033\fs24 , Apostel und Evangelist, im \u214 \'d6lkessel. 40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[8]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 T\u246 \'f6tung der unschuldigen Kinder}}\plain \f1\lang1033\fs24 . 42\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ermordung des hl. Thomas von Canterbury}}\plain \f1\lang1033\fs24   in seiner Kathedrale. 44\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   thronender {\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Silvester}}\plain \f1\lang1033\fs24 . 49\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[11]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Beschneidung des Herrn}}\plain \f1\lang1033\fs24 . 53\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[12]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Anbetung der hl. Drei K\u246 \'f6nige}}\plain \f1\lang1033\fs24 . 57\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   hl. Eremit Paulus, als erster \u228 \'e4gyptischer Einsiedler in einer H\u246 \'f6hle. 58\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   thronender {\field{\*\fldinst HYPERLINK "hida://5500[13]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Bischof Remigius}}\plain \f1\lang1033\fs24 . 59\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[14]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Hilarius}}\plain \f1\lang1033\fs24   mit