\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ornamentale Initialen}}\plain \f1\lang1033\fs24  in Deckfarben und Gold  (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 39\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 81\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 85\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 101\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 ): 3\endash 8-zeilige Initiale (H\u246 \'f6he: 1,5\endash 3,5 cm) mit einfarbigem Stamm mit Wei\u223 \'dflinienfiligran (Konturen, Bogenreihen, gewundenes Band, Perlen, Punkte, U-H\u228 \'e4kchen) vor rechteckigem, an den Ecken jeweils durch Pollen ausgeweitetem und links vertikal eingebuchtetem goldenen Feld, das nach oben und unten in langgezogene, den vertikalen Schriftspiegel s\u228 \'e4umende Gold- und Farbleisten \u252 \'fcbergeht, an denen bunte Dornbl\u228 \'e4tter sitzen, umstreut von gestielten Goldpollen; Bl. 68\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   oben horizontal in einen Drachenleib \u252 \'fcbergehend. Binnenraum: farbige Ranken mit breiten Profilbl\u228 \'e4ttern und Farbpollen vor goldenem Grund. Farben: Blau, Hell- und Dunkelrosa, Hellrot, Wei\u223 \'df, Schwarz, Blattgold.  }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Calibri;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

