\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 Inhalt\plain \f1\lang1033\fs24 : I\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant. 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Psalmen. 15\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Gebet zur Dreieinigkeit. 25\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Gebet zur Jungfrau Maria. 38\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Gebet zum hl. Thomas von Aquin. 40\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 79\plain \f1\super\lang1033\fs24 r \plain \f1\lang1033\fs24  verschiedene Gebete. 79\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Marienmesse. 83\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 103\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Messe zur Passion Christi. 104\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 132\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Mariengebete (und diverse andere Gebete). 132\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 146\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Totenmesse. 146\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 155\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   verschiedene Gebete. 155\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 187\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Psalterium Marianum. 187\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacat. 188\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 192\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Messe des hl. Kreuzes. 193\plain \f1\super\lang1033\fs24 r\endash v\plain \f1\lang1033\fs24   vacant.}

