\pard\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  Heller {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ledereinband}}\plain \f1\lang1033\fs24   mit {\field{\*\fldinst HYPERLINK "hida://5300[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Streicheisenlinien}}\plain \f1\lang1033\fs24   (Vorderdeckel: zwei einfache Streifenrahmen; hinterer Deckel: einfacher Streifenrahmen, Mittelteil rautenf\u246 \'f6rmig geteilt [3 : 3]) und {\field{\*\fldinst HYPERLINK "hida://5300[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Einzelstempeln}}\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  (z. B. Bl\u252 \'fctenstaude im Aufschnitt [{\field{\*\fldinst HYPERLINK "hida://6560[0].6770/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 EBDB s026582}}\plain \f1\lang1033\fs24  ], Rautengerank mit Besatz\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  [{\field{\*\fldinst HYPERLINK "hida://6560[1].6770/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 EBDB s026579}}\plain \f1\lang1033\fs24\cf1 ], Rhombus mit Lilie [{\field{\*\fldinst HYPERLINK "hida://6560[2].6770/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17\cf1 EBDB\~s026576}}\plain \f1\lang1033\fs24\cf1 ]\plain \f1\lang1033\fs24 ),\plain \f1\b\lang1033\fs24   \plain \f1\lang1033\fs24  Zisterzienserkloster Kaisheim ({\field{\*\fldinst HYPERLINK "hida://bezsoz[0].4998/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 EBDB w002273}}\plain \f1\lang1033\fs24 ), sp\u228 \'e4tgotisch. Unmittelbar auf Vorderdeckel Titel aufgeschrieben. Am R\u252 \'fccken altes Bibliotheksschildchen (\plain \f1\i\lang1033\fs24  Kaisersh. 36\plain \f1\i\super\lang1033\fs24 c\plain \f1\lang1033\fs24 ).}

