\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Hiob; 144\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Tobias; 148\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Jeremia; 150\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Jeremia und Daniel; 158\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 165\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Judith; 165\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Esther; 172\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 193\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Paralipomenon; 193\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Esra; 196\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 200\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Nehemia; 200\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  \endash 205\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Esra). 206\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 208\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   vacant.}

