\par \pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 Kleine {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24   (z. B. 84\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 84\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 85\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 94\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): 2\endash 4-zeilige rote und blaue Lombarden im Wechsel (Init.-H\u246 \'f6he: 1\endash 2 cm), die roten Lombarden mit gr\u252 \'fcnem (vereinzelt mit lilafarbenem [z. B. 92\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  ]) Fleuronn\u233 \'e9e, die blauen Lombarden mit rotem Fleuronn\u233 \'e9e. Besatz: konturbegleitende F\u228 \'e4den (auch mit Punktverdickung) oder Stege, Voluten, schr\u228 \'e4g abstehende Staubf\u228 \'e4den, links nach oben und unten um geraden Steg verl\u228 \'e4ngert, an dem Kreissegmente, Schlaufen, Zacken \endash  jeweils mit Kern \endash  sowie querst\u228 \'e4ndige kurze Parallelf\u228 \'e4den, Perlen (einzeln, Kette) und Staubf\u228 \'e4den bzw. S-Kringel h\u228 \'e4ngen, jeweils am Ende in Einzelf\u228 \'e4den mit Haarnadelkurve oder Kurve (auch mit schr\u228 \'e4gsitzendem Staubfaden) auslaufend. Binnenraum: konturbegleitende F\u228 \'e4den und Stege, querst\u228 \'e4ndige und schr\u228 \'e4ge Stege (auch geschwungen), Perlen (einzeln, gestielt, Reihen [auch mit jeweils kurzen zwischengeschalteten Querf\u228 \'e4den], Ketten), Punkte.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Gro\u223 \'dfe {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fleuronn\u233 \'e9e-Initialen}}\plain \f1\lang1033\fs24  mit Fleuronn\u233 \'e9est\u228 \'e4ben  (87\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 88\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 91\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ): 4\endash 6-zeilige Initialen mit rot/blau ornamental gespaltenem Stamm, in den auch rote und gr\u252 \'fcne (bzw. ausgesparte) Motive (wie Kleebl\u228 \'e4tter und Trifolien) integriert sind (Init.-H\u246 \'f6he: 2,5\endash 3,5 cm). Besatz: blockartige Erweiterung durch Stege (mit anhaftenden Perlen, Fransen, abstehenden Staubf\u228 \'e4den), Zwickelbl\u228 \'e4tter oder -blattkonstellationen, links nach oben und unten abgehende Ausl\u228 \'e4ufer (wie bei kleinen Fleuronn\u233 \'e9e-Initialen), die von Fleuronn\u233 \'e9est\u228 \'e4ben (Farbleisten, Kreissegmente mit parallel folgenden Stegen, Keilformen, abstehenden S-Kringeln) unterbrochen werden, in denen wiederum zahlreiche vergr\u246 \'f6\u223 \'dferte Medaillons (umrahmt von Kreisen mit gestielten querst\u228 \'e4ndigen Perlen, abstehenden kurzen Fransen und anhaftenden Perlen) sitzen, deren Binnenraum jeweils zoomorphe (Mischwesen, V\u246 \'f6gel, sich umblickende bzw. jaulende Hunde mit zwei Beinen) und anthropomorphe (z. B. menschliche Fratze, Profilgesicht) Elemente, aber auch Blattwerk oder geometrische Aussparungen vor Farbgrund birgt. Binnenraum: konturbegleitende rot und gr\u252 \'fcn gezeichnete Blattranken- oder Knospenleisten (mit durchscheinendem Pergament), zoomorphe Elemente (hunde\u228 \'e4hnliche Zweibeiner) vor einfarbigem Grund, Knospen\u228 \'e4hren.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

