\uc1
\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Historisierte Initiale}}\plain \f1\lang1033\fs24   (Gestaltung und Farben wie ornamentale Initialen, zus\u228 \'e4tzlich Grau, Braun): 185\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 hl. Augustinus}}\plain \f1\lang1033\fs24 , in D(\plain \f1\i\lang1033\fs24  eus propicius esto michi\plain \f1\lang1033\fs24 ). 8-zeilige Initiale (H\u246 \'f6he: 3,5 cm) mit rosafarbenem K\u246 \'f6rper und Wei\u223 \'dflinienfiligran (Fadenranken, Punkte), das auch den rechteckigen (bzw. links ausgebuchteten) blauen Grund \u252 \'fcberzieht. Binnenraum: auf einem Kissen thronend die frontale Sicht auf den hl. Augustinus mit Mitra und Bischofsstab.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 @Arial Unicode MS;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

