\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 \plain \f1\lang1033\fs24 Kalenderk\u252 \'fcrzel mit kleinen runden {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Miniaturen}}\plain \f1\lang1033\fs24   (1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \endash 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   goldenes K\u252 \'fcrzel [KL], umgeben von Fleuronn\u233 \'e9e, w\u228 \'e4hrend im Binnenraum einfarbiger Grund mit Fadenranken, Perlen und Punkten steht): jeweils pro Seite zwei Medaillons mit {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Monatsarbeit}}\plain \f1\lang1033\fs24   und Zodiakalzeichen: 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Tafelnder, {\field{\*\fldinst HYPERLINK "hida://5500[3]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wassermann}}\plain \f1\lang1033\fs24 . 1\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   sitzender Mann w\u228 \'e4rmt sich am Feuer, {\field{\*\fldinst HYPERLINK "hida://5500[4]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Fische}}\plain \f1\lang1033\fs24 . 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[17]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Bauer mit Spaten}}\plain \f1\lang1033\fs24   beim Umgraben, {\field{\*\fldinst HYPERLINK "hida://5500[5]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Widder}}\plain \f1\lang1033\fs24 . 2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   neben Pferd stehender Ritter mit Fahne, {\field{\*\fldinst HYPERLINK "hida://5500[6]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Stier}}\plain \f1\lang1033\fs24 . 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[14]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Liebespaar}}\plain \f1\lang1033\fs24   (M\u228 \'e4dchen und Falkner), {\field{\*\fldinst HYPERLINK "hida://5500[7]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Zwillinge}}\plain \f1\lang1033\fs24 . 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Mann mit {\field{\*\fldinst HYPERLINK "hida://5500[19]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sense}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5500[8]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Krebs}}\plain \f1\lang1033\fs24 . 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   Mann mit Rechen, {\field{\*\fldinst HYPERLINK "hida://5500[9]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 L\u246 \'f6we}}\plain \f1\lang1033\fs24 . 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   geb\u252 \'fcckter {\field{\*\fldinst HYPERLINK "hida://5500[21]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Mann m\u228 \'e4ht mit Sichel}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5500[10]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Jungfrau}}\plain \f1\lang1033\fs24 . 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   {\field{\*\fldinst HYPERLINK "hida://5500[15]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Weinernte}}\plain \f1\lang1033\fs24   und {\field{\*\fldinst HYPERLINK "hida://5500[16]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kelter}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5500[11]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Waage}}\plain \f1\lang1033\fs24 . 5\plain \f1\super\lang1033\fs24 v {\field{\*\fldinst HYPERLINK "hida://5500[1]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 S\u228 \'e4ender}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5500[12]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Skorpion}}\plain \f1\lang1033\fs24 . 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24   weidende {\field{\*\fldinst HYPERLINK "hida://5500[18]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Schweine}}\plain \f1\lang1033\fs24 , {\field{\*\fldinst HYPERLINK "hida://5500[13]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Sch\u252 \'fctze}}\plain \f1\lang1033\fs24 . 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24   Schlachten eines Schweines, {\field{\*\fldinst HYPERLINK "hida://5500[2]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Steinbock}}\plain \f1\lang1033\fs24 . }

