\pard\sl256\slmult1\fi0\li0\ql\ri0\sb0\sa165\itap0 {\field{\*\fldinst HYPERLINK "hida://5240/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Wappen}}\plain \f1\lang1033\fs24  und Devisen  (Zeichnung und Deckfarben: teils auf Schilden, teils auf Bannern [mit und ohne Stangen]; aufgelistet und bestimmt in Libro del Conos\u231 \'e7imiento, S. 71-74 [2\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 3\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 3\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 4\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 4\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 5\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 5\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 6\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 6\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 7\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 7\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 8\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 8\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 9\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 9\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 10\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 11\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 12\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 12\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 13\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 14\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 15\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 16\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 16\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 17\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 17\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 19\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 19\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 20\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  ]): sie begleiten die Reise von Kastilien, Portugal, Bayonne \u252 \'fcber Navarra, Toulouse, Frankreich, Brabant, Deutschland, Ostfriesland, D\u228 \'e4nemark, B\u246 \'f6hmen, Litauen, Polen, Lemberg, Schweden, Norwegen, Shetland Inseln, Schottland, England, Irland, Island, Granada, Aragon, Narbonne, Genf, Lombardei, Pisa, Florenz, Rom, Neapel, Sizilien, Venedig, Slawonien, Bosnien, Dalmatien, Ungarn, Rhodos, Antalya, T\u252 \'fcrkei, Armenien, Zypern, Syrien, Damaskus, \u196 \'c4gypten, Alexandria, Tripolis, Tunesien, Korsika, Mallorca, Marrakesch, Buda, Ghana, Nubien, Mali, Kongo, \u196 \'c4thiopien, Mogadischu, Bagdad, Irak, Mekka, Dehli, Java, China bis nach Persien. Farben: Hellrot, Blau, Gr\u252 \'fcn, Gelb, Ocker, Braun, Grau, Schwarz, Wei\u223 \'df. }

